// Supabase Edge Function "bb": the whole Bookingbooster back end. app.mjs is generated by supabase/build.js.
import postgres from 'npm:postgres@3.4.7';
(globalThis as any).__bbPostgres = postgres;
import load from './app.mjs';

const serve = load({ proxyKey: Deno.env.get('PROXY_KEY') || '', prefix: '/bb' });
const waitUntil = (p: Promise<unknown>) => { try { (globalThis as any).EdgeRuntime.waitUntil(p); } catch (_) { /* local run */ } };

// A stray rejected promise must not take the whole function down: log it and carry on.
globalThis.addEventListener('unhandledrejection', (e: PromiseRejectionEvent) => { e.preventDefault(); console.log('unhandled', e.reason && (e.reason.stack || e.reason.message || e.reason)); });
const handler = (req: Request) => serve(req, (globalThis as any).EdgeRuntime ? waitUntil : null);
const local = Deno.env.get('BB_LOCAL_PORT'); // local test runs only (test/harness.js with BB_DENO=1)
if (local) Deno.serve({ port: +local, hostname: '127.0.0.1', onListen() {} }, handler); else Deno.serve(handler);
